// The installed themes' manifest, as the image ships it (generated by the web build).
const repoThemeBlockManifest = "../web/themes/blocks.manifest.json"

func loadRepoThemeBlocks(t *testing.T) ThemeBlockManifest {
	t.Helper()
	manifest, found, err := LoadThemeBlockManifest(repoThemeBlockManifest)
	require.NoError(t, err)
	require.True(t, found, "web/themes/blocks.manifest.json is missing: run `npm run themes:manifest` in web/")
	return manifest
}

func themeBlockDoc(blocks map[string]interface{}) *BlockDocV1 {
	order := make([]string, 0, len(blocks))
	for id := range blocks {
		order = append(order, id)
	}
	return &BlockDocV1{DocVersion: 1, BlocksOrder: order, Blocks: blocks}
}

// roundTrip turns Go literals into what JSON decoding gives (float64 numbers etc.).
func roundTrip(t *testing.T, v interface{}) map[string]interface{} {
	t.Helper()
	raw, err := json.Marshal(v)
	require.NoError(t, err)
	var out map[string]interface{}
	require.NoError(t, json.Unmarshal(raw, &out))
	return out
}

// TestThemeBlockVectors runs the cases shared with the collab server's validation
// (web/gl-admin/lib/blocks-spec/themeBlockVectors.json): both sides must accept and
// refuse the same blocks, or a store the collab server sends could be refused.
func TestThemeBlockVectors(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join("..", "web", "gl-admin", "lib", "blocks-spec", "themeBlockVectors.json"))
	require.NoError(t, err)
	var vectors struct {
		Spec struct {
			Type string `json:"type"`
			ThemeBlockSpec
		} `json:"spec"`
		Cases []struct {
			Name       string                 `json:"name"`
			Block      map[string]interface{} `json:"block"`
			Valid      bool                   `json:"valid"`
			AttrsAfter map[string]interface{} `json:"attrs_after"`
		} `json:"cases"`
	}
	require.NoError(t, json.Unmarshal(raw, &vectors))
	require.NotEmpty(t, vectors.Cases)
	manifest := ThemeBlockManifest{ManifestVersion: 1, Blocks: map[string]ThemeBlockSpec{vectors.Spec.Type: vectors.Spec.ThemeBlockSpec}}

	for _, tc := range vectors.Cases {
		t.Run(tc.Name, func(t *testing.T) {
			block := tc.Block
			block["id"] = "blk-vector-0001"
			block["type"] = vectors.Spec.Type
			doc := themeBlockDoc(map[string]interface{}{"blk-vector-0001": block})
			err := doc.prepareForStore(manifest)
			if !tc.Valid {
				require.Error(t, err)
				return
			}
			require.NoError(t, err)
			require.Equal(t, tc.AttrsAfter, doc.Blocks["blk-vector-0001"].(map[string]interface{})["attrs"])
		})
	}
}

func TestThemeBlocks_ExampleAlert(t *testing.T) {
	manifest := loadRepoThemeBlocks(t)
	require.Contains(t, manifest.Blocks, "theme:example/alert")

	alert := func(attrs map[string]interface{}) map[string]interface{} {
		return roundTrip(t, map[string]interface{}{"id": "blk-alert-00001", "type": "theme:example/alert", "version": 1, "attrs": attrs})
	}

	t.Run("accepted, with undeclared attrs and pm attrs stripped", func(t *testing.T) {
		doc := themeBlockDoc(map[string]interface{}{"blk-alert-00001": alert(map[string]interface{}{
			"variant": "warning",
			"message": "an attr from the pre-#376 alert",
			"text":    "Mind the gap",
			"pm": map[string]interface{}{
				"type":    "theme:example/alert",
				"attrs":   map[string]interface{}{"variant": "error"},
				"content": []interface{}{map[string]interface{}{"type": "text", "text": "Mind the gap"}},
			},
		})})
		require.NoError(t, doc.prepareForStore(manifest))
		attrs := doc.Blocks["blk-alert-00001"].(map[string]interface{})["attrs"].(map[string]interface{})
		require.Equal(t, "warning", attrs["variant"])
		require.NotContains(t, attrs, "message")
		require.Equal(t, "Mind the gap", attrs["text"])
		require.NotContains(t, attrs["pm"], "attrs")
	})

	t.Run("an invalid variant refuses the document", func(t *testing.T) {
		doc := themeBlockDoc(map[string]interface{}{"blk-alert-00001": alert(map[string]interface{}{"variant": "<script>"})})
		require.ErrorContains(t, doc.prepareForStore(manifest), "attr variant")
	})

	t.Run("a version newer than the build reads is kept as is (a newer build wrote it)", func(t *testing.T) {
		block := alert(map[string]interface{}{"variant": "v2-only", "extra": "x"})
		block["version"] = float64(2)
		doc := themeBlockDoc(map[string]interface{}{"blk-alert-00001": block})
		require.NoError(t, doc.prepareForStore(manifest))
		require.Equal(t, map[string]interface{}{"variant": "v2-only", "extra": "x"}, doc.Blocks["blk-alert-00001"].(map[string]interface{})["attrs"])
	})

	t.Run("a version that isn't a positive integer refuses the document", func(t *testing.T) {
		block := alert(map[string]interface{}{})
		block["version"] = float64(0)
		doc := themeBlockDoc(map[string]interface{}{"blk-alert-00001": block})
		require.ErrorContains(t, doc.prepareForStore(manifest), "version")
	})

	t.Run("the generic sanitizer still runs on theme content", func(t *testing.T) {
		doc := themeBlockDoc(map[string]interface{}{"blk-alert-00001": alert(map[string]interface{}{
			"pm": map[string]interface{}{
				"type": "theme:example/alert",
				"content": []interface{}{
					map[string]interface{}{"type": "text", "text": "x", "marks": []interface{}{
						map[string]interface{}{"type": "link", "attrs": map[string]interface{}{"href": "javascript:alert(1)"}},
					}},
					map[string]interface{}{"type": "script"},
				},
			},
		})})
		require.NoError(t, doc.prepareForStore(manifest))
		content := doc.Blocks["blk-alert-00001"].(map[string]interface{})["attrs"].(map[string]interface{})["pm"].(map[string]interface{})["content"].([]interface{})
		require.Len(t, content, 1)
		require.Empty(t, content[0].(map[string]interface{})["marks"])
	})

	t.Run("a block of a theme that isn't installed is kept as is (only sanitized)", func(t *testing.T) {
		gone := roundTrip(t, map[string]interface{}{"id": "blk-gone-000001", "type": "theme:gone/widget", "version": 7,
			"attrs": map[string]interface{}{"size": 4, "onclick": "x", "text": "kept"}})
		doc := themeBlockDoc(map[string]interface{}{"blk-gone-000001": gone})
		require.NoError(t, doc.prepareForStore(manifest))
		require.Equal(t, map[string]interface{}{"size": float64(4), "text": "kept"}, doc.Blocks["blk-gone-000001"].(map[string]interface{})["attrs"])
		require.Equal(t, float64(7), doc.Blocks["blk-gone-000001"].(map[string]interface{})["version"])
	})

	t.Run("without a manifest, theme blocks are kept opaque", func(t *testing.T) {
		doc := themeBlockDoc(map[string]interface{}{"blk-alert-00001": alert(map[string]interface{}{"variant": "nope"})})
		require.NoError(t, doc.prepareForStore(ThemeBlockManifest{}))
	})
}

func TestLoadThemeBlockManifest(t *testing.T) {
	dir := t.TempDir()
	write := func(name, content string) string {
		path := filepath.Join(dir, name)
		require.NoError(t, os.WriteFile(path, []byte(content), 0o600))
		return path
	}

	_, found, err := LoadThemeBlockManifest(filepath.Join(dir, "missing.json"))
	require.NoError(t, err)
	require.False(t, found)

	for name, content := range map[string]string{
		"not-json.json":     "{",
		"version.json":      `{"manifest_version": 2, "blocks": {}}`,
		"prefix.json":       `{"manifest_version": 1, "blocks": {"alert": {"version": 1, "attrs": {}}}}`,
		"zero-version.json": `{"manifest_version": 1, "blocks": {"theme:x/y": {"version": 0, "attrs": {}}}}`,
		"attr-type.json":    `{"manifest_version": 1, "blocks": {"theme:x/y": {"version": 1, "attrs": {"a": {"type": "object"}}}}}`,
	} {
		_, found, err := LoadThemeBlockManifest(write(name, content))
		require.Error(t, err, name)
		require.True(t, found, name)
	}

	manifest := loadRepoThemeBlocks(t)
	require.Equal(t, 1, manifest.ManifestVersion)
}

// The collab server's store goes through the same checks (#376).
func TestPutInternalPostCollab_ThemeBlocks(t *testing.T) {
	const path = "/internal/posts/7/collab"
	auth := "Bearer " + testRoleLookupSecret
	body := func(variant string) []byte {
		return collabStoreBody(t, map[string]any{"block_doc": map[string]any{
			"doc_version":  1,
			"blocks_order": []string{"blk-alert-00001"},
			"blocks": map[string]any{"blk-alert-00001": map[string]any{
				"id": "blk-alert-00001", "type": "theme:example/alert", "version": 1,
				"attrs": map[string]any{"variant": variant, "message": "stripped", "text": "Careful"},
			}},
		}})
	}

	t.Run("a valid alert is stored without undeclared attrs", func(t *testing.T) {
		ctrl := gomock.NewController(t)
		store := mockdb.NewMockStore(ctrl)
		store.EXPECT().StorePostCollabTx(gomock.Any(), gomock.Any()).Times(1).
			DoAndReturn(func(_ any, arg db.StorePostCollabTxParams) (db.StorePostCollabTxResult, error) {
				var doc BlockDocV1
				require.NoError(t, json.Unmarshal(arg.BlockDoc, &doc))
				attrs := doc.Blocks["blk-alert-00001"].(map[string]interface{})["attrs"].(map[string]interface{})
				require.Equal(t, map[string]interface{}{"variant": "error", "text": "Careful"}, attrs)
				return db.StorePostCollabTxResult{BlockRevision: 5}, nil
			})
		server := newTestServer(t, store)
		server.themeBlocks = loadRepoThemeBlocks(t)
		recorder := internalCollabRequest(t, server, http.MethodPut, path, body("error"), auth)
		require.Equal(t, http.StatusOK, recorder.Code, recorder.Body.String())
	})

	t.Run("an invalid variant is refused before anything is stored", func(t *testing.T) {
		ctrl := gomock.NewController(t)
		store := mockdb.NewMockStore(ctrl)
		store.EXPECT().StorePostCollabTx(gomock.Any(), gomock.Any()).Times(0)
		server := newTestServer(t, store)
		server.themeBlocks = loadRepoThemeBlocks(t)
		recorder := internalCollabRequest(t, server, http.MethodPut, path, body("purple"), auth)
		require.Equal(t, http.StatusBadRequest, recorder.Code)
		require.Contains(t, recorder.Body.String(), "theme:example/alert")
	})
}
